"""Export Page 1 运营管理-* frames from figma-file-raw.json to docs/figma-page1-screens.md."""
from __future__ import annotations

import json
import re
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
FIGMA_JSON = ROOT / "figma-file-raw.json"
OUT_MD = Path(__file__).resolve().parents[1] / "docs" / "figma-page1-screens.md"

SKIP_NAMES = {
    "Content",
    "Page",
    "Rectangle 2",
    "Rectangle 3",
    "封面",
    "员工列表",
}
SKIP_PREFIXES = ("Frame ", "image ")


def text_value(node: dict) -> str:
    chars = node.get("characters")
    return " ".join(str(chars).split()) if chars else ""


def bbox(node: dict) -> tuple[float, float]:
    box = node.get("absoluteBoundingBox") or {}
    return round(box.get("width", 0), 1), round(box.get("height", 0), 1)


def collect_texts(node: dict, limit: int = 40) -> list[str]:
    out: list[str] = []

    def walk(n: dict) -> None:
        if len(out) >= limit:
            return
        if n.get("type") == "TEXT":
            t = text_value(n)
            if t and t not in out:
                out.append(t)
        for c in n.get("children") or []:
            walk(c)

    walk(node)
    return out


def should_include(name: str) -> bool:
    if not name.startswith("运营管理-"):
        return False
    if name in SKIP_NAMES:
        return False
    return not any(name.startswith(p) for p in SKIP_PREFIXES)


def main() -> None:
    data = json.loads(FIGMA_JSON.read_text(encoding="utf-8-sig"))
    page1 = next(
        (p for p in data["document"]["children"] if p.get("name") == "Page 1"),
        None,
    )
    if not page1:
        raise SystemExit("Page 1 not found in figma JSON")

    frames: dict[str, dict] = {}
    for child in page1.get("children") or []:
        if child.get("type") != "FRAME":
            continue
        name = child.get("name", "")
        if not should_include(name):
            continue
        fid = child.get("id", "")
        w, h = bbox(child)
        key = name
        if key not in frames or (w * h) > (frames[key]["width"] * frames[key]["height"]):
            frames[key] = {
                "id": fid,
                "name": name,
                "width": w,
                "height": h,
                "texts": collect_texts(child),
                "children": [
                    {
                        "name": c.get("name"),
                        "id": c.get("id"),
                        "type": c.get("type"),
                        "size": bbox(c),
                    }
                    for c in (child.get("children") or [])[:6]
                ],
            }

    lines = [
        "# Figma Page 1 — 运营管理画板清单",
        "",
        f"来源：`{FIGMA_JSON.name}`，文件 key `NdIFQRMnOPTlx59LrH0SXu`",
        "",
        "| 画板 | Node ID | 尺寸 | 路由 |",
        "|------|---------|------|------|",
    ]

    route_map = {
        "运营管理-业务看板": "/",
        "运营管理-用户反馈": "/feedback",
        "运营管理-专家工作台": "/expert",
        "运营管理-模型看板": "/model-board",
        "运营管理-资源看板": "/resource-board",
        "运营管理-资源与成本管理": "/resource-cost",
        "运营管理-用户与智能体画像": "/profile",
        "运营管理-模型运营": "/model-ops",
        "运营管理-智能体运营": "/agent-ops",
        "运营管理-权限与开发者管理": "/permission",
        "运营管理-权限与开发者管理-用户管理": "/permission/users",
        "运营管理-权限与开发者管理-组织架构": "/permission/orgs",
        "运营管理-权限与开发者管理-角色管理": "/permission/roles",
        "运营管理-权限与开发者管理-权限定义": "/permission/acl",
    }

    for name in sorted(frames.keys()):
        f = frames[name]
        route = route_map.get(name, "—")
        node_url = f"https://www.figma.com/design/NdIFQRMnOPTlx59LrH0SXu?node-id={f['id'].replace(':', '-')}"
        lines.append(
            f"| [{name}]({node_url}) | `{f['id']}` | {f['width']}×{f['height']} | `{route}` |"
        )

    lines.extend(["", "## 画板详情", ""])
    for name in sorted(frames.keys()):
        f = frames[name]
        lines.append(f"### {name} (`{f['id']}`)")
        lines.append("")
        lines.append(f"- 尺寸：{f['width']} × {f['height']}")
        if f["children"]:
            lines.append("- 一级子节点：")
            for c in f["children"]:
                lines.append(
                    f"  - `{c['name']}` ({c['type']}, `{c['id']}`, {c['size'][0]}×{c['size'][1]})"
                )
        if f["texts"]:
            lines.append("- 关键文案：")
            for t in f["texts"][:25]:
                lines.append(f"  - {t}")
        lines.append("")

    OUT_MD.parent.mkdir(parents=True, exist_ok=True)
    OUT_MD.write_text("\n".join(lines), encoding="utf-8")
    print(f"Wrote {len(frames)} frames to {OUT_MD}")


if __name__ == "__main__":
    main()

from fastapi import FastAPI, HTTPException
from fastapi.middleware.cors import CORSMiddleware
from pydantic import BaseModel

from app import mock_data

app = FastAPI(
    title="Aoqin Ops Platform Demo API",
    description="Mock API for Figma Page 1 operations management demo.",
    version="1.0.0",
)

app.add_middleware(
    CORSMiddleware,
    allow_origins=[
        "http://localhost:5180",
        "http://127.0.0.1:5180",
    ],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)


class FeedbackPatch(BaseModel):
    status: str | None = None


class ExpertTaskPatch(BaseModel):
    status: str | None = None
    assignee: str | None = None


@app.get("/api/health")
def health() -> dict[str, str]:
    return {"status": "ok", "service": "aoqin-ops-demo-api"}


@app.get("/api/ops/dashboard-metrics")
def dashboard_metrics() -> dict:
    return mock_data.get_dashboard()


@app.get("/api/ops/feedback")
def list_feedback(status: str | None = None) -> list[dict]:
    return mock_data.get_feedback(status)


@app.patch("/api/ops/feedback/{feedback_id}")
def update_feedback(feedback_id: str, body: FeedbackPatch) -> dict:
    updated = mock_data.patch_feedback(feedback_id, body.model_dump(exclude_none=True))
    if not updated:
        raise HTTPException(status_code=404, detail="Feedback not found")
    return updated


@app.get("/api/ops/expert-tasks")
def list_expert_tasks() -> list[dict]:
    return mock_data.get_expert_tasks()


@app.patch("/api/ops/expert-tasks/{task_id}")
def update_expert_task(task_id: str, body: ExpertTaskPatch) -> dict:
    updated = mock_data.patch_expert_task(task_id, body.model_dump(exclude_none=True))
    if not updated:
        raise HTTPException(status_code=404, detail="Task not found")
    return updated

