type RequestOptions = { method?: string; body?: unknown };

export async function mockApi<T>(path: string, options: RequestOptions = {}): Promise<T> {
  await new Promise((r) => setTimeout(r, 80));

  if (path.startsWith("/ops/dashboard-metrics")) {
    return DASHBOARD as T;
  }

  if (path.startsWith("/ops/feedback")) {
    const parts = path.split("/");
    if (parts.length >= 4 && options.method === "PATCH") {
      const id = parts[3];
      const body = options.body as { status?: string };
      const item = FEEDBACK.find((f) => f.id === id);
      if (item && body.status) item.status = body.status;
      return item as T;
    }
    const q = path.includes("?") ? new URLSearchParams(path.split("?")[1]) : null;
    const status = q?.get("status");
    let list = [...FEEDBACK];
    if (status && status !== "全部") {
      list = list.filter((f) => f.status === status);
    }
    return list as T;
  }

  if (path.startsWith("/ops/expert-tasks")) {
    const parts = path.split("/");
    if (parts.length >= 4 && options.method === "PATCH") {
      const id = parts[3];
      const body = options.body as { status?: string; assignee?: string };
      const item = EXPERT.find((t) => t.id === id);
      if (item) {
        if (body.status) item.status = body.status;
        if (body.assignee) item.assignee = body.assignee;
      }
      return item as T;
    }
    return [...EXPERT] as T;
  }

  throw new Error(`Mock path not found: ${path}`);
}

import { mockApi } from "./mockData";

const API_BASE = import.meta.env.VITE_API_BASE ?? "/api";
const FORCE_MOCK = import.meta.env.VITE_FORCE_MOCK === "true";

type RequestOptions = {
  method?: string;
  body?: unknown;
};

export async function api<T>(path: string, options: RequestOptions = {}): Promise<T> {
  if (FORCE_MOCK) {
    return mockApi<T>(path, options);
  }

  try {
    const response = await fetch(`${API_BASE}${path}`, {
      method: options.method ?? "GET",
      headers: { "Content-Type": "application/json" },
      body: options.body ? JSON.stringify(options.body) : undefined,
    });

    const contentType = response.headers.get("content-type") ?? "";
    if (!response.ok || !contentType.includes("application/json")) {
      throw new Error(`API ${path} failed: ${response.status}`);
    }

    return response.json() as Promise<T>;
  } catch {
    return mockApi<T>(path, options);
  }
}

