const MAP: Record<string, string> = {
  致命: "danger",
  严重: "danger",
  一般: "warning",
  建议: "info",
};

export function SeverityTag({ value }: { value: string }) {
  const cls = MAP[value] ?? "muted";
  return <span className={`ops-tag ${cls}`}>{value}</span>;
}

type Metric = { label: string; value: string | number; hint?: string };

export function MetricCards({ metrics }: { metrics: Metric[] }) {
  return (
    <div className="ops-card-grid">
      {metrics.map((m) => (
        <div className="ops-metric-card" key={m.label}>
          <span>{m.label}</span>
          <strong>{m.value}</strong>
          {m.hint ? <small style={{ color: "var(--ops-text-muted)" }}>{m.hint}</small> : null}
        </div>
      ))}
    </div>
  );
}

export function TokenTrendChart({ data, title }: { data: number[]; title: string }) {
  const max = Math.max(...data, 1);
  return (
    <div className="ops-chart-box">
      <h3>{title}</h3>
      <div className="ops-bar-chart">
        {data.map((v, i) => (
          <div
            key={i}
            className="ops-bar"
            style={{ height: `${(v / max) * 100}%` }}
            title={`${v}`}
          />
        ))}
      </div>
    </div>
  );
}

