const TABS = ["全部", "处理中", "已完成", "待处理"] as const;

export default function UserFeedbackPage() {
  const [tab, setTab] = useState<(typeof TABS)[number]>("全部");
  const [items, setItems] = useState<FeedbackItem[]>([]);
  const [category, setCategory] = useState("全部");

  function load() {
    const q = tab === "全部" ? "" : `?status=${encodeURIComponent(tab)}`;
    api<FeedbackItem[]>(`/ops/feedback${q}`).then(setItems);
  }

  useEffect(() => {
    load();
  }, [tab]);

  async function advance(item: FeedbackItem) {
    const next =
      item.status === "待处理" ? "处理中" : item.status === "处理中" ? "已完成" : "已完成";
    await api<FeedbackItem>(`/ops/feedback/${item.id}`, {
      method: "PATCH",
      body: { status: next },
    });
    load();
  }

  const filtered =
    category === "全部" ? items : items.filter((i) => i.category === category);

  return (
    <>
      <h1 className="ops-page-title">用户反馈</h1>
      <p className="ops-page-desc">
        运营管理 — 用户反馈列表与处理（Figma node 0:5436 / Container 0:5491）
      </p>
      <div className="ops-tabs">
        {TABS.map((t) => (
          <button key={t} type="button" className={tab === t ? "active" : ""} onClick={() => setTab(t)}>
            {t}
          </button>
        ))}
      </div>
      <div className="ops-two-col">
        <aside className="ops-filter-panel">
          <strong style={{ fontSize: 14 }}>筛选</strong>
          <label>反馈类型</label>
          <select value={category} onChange={(e) => setCategory(e.target.value)}>
            <option>全部</option>
            <option>内容错误</option>
            <option>UI异常</option>
          </select>
          <label>严重程度</label>
          <select>
            <option>全部</option>
            <option>严重</option>
            <option>一般</option>
            <option>建议</option>
          </select>
          <button type="button" className="ops-btn primary" style={{ marginTop: 16, width: "100%" }}>
            应用筛选
          </button>
        </aside>
        <section className="ops-panel">
          <div className="ops-filter-bar" style={{ padding: "12px 14px" }}>
            <span style={{ fontSize: 13, color: "var(--ops-text-muted)" }}>共 {filtered.length} 条反馈</span>
          </div>
          <table className="ops-table">
            <thead>
              <tr>
                <th>严重程度</th>
                <th>标题</th>
                <th>类型</th>
                <th>关联智能体</th>
                <th>提交者</th>
                <th>状态</th>
                <th>操作</th>
              </tr>
            </thead>
            <tbody>
              {filtered.map((item) => (
                <tr key={item.id}>
                  <td>
                    <SeverityTag value={item.severity} />
                  </td>
                  <td>{item.title}</td>
                  <td>
                    <span className="ops-tag muted">{item.category}</span>
                  </td>
                  <td>{item.agent}</td>
                  <td>{item.submitter}</td>
                  <td>
                    <span className={`ops-tag ${item.status === "已完成" ? "success" : item.status === "处理中" ? "info" : "warning"}`}>
                      {item.status}
                    </span>
                  </td>
                  <td>
                    <button type="button" className="ops-btn" onClick={() => advance(item)}>
                      推进
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </section>
      </div>
    </>
  );
}

