import { useEffect, useState } from "react";

import { OpsPageShell } from "./components/layout/OpsPageShell";
import BusinessDashboardPage from "./pages/BusinessDashboardPage";
import ModelBoardPage, { ResourceBoardPage } from "./pages/BoardPage";
import ExpertWorkbenchPage from "./pages/ExpertWorkbenchPage";
import { AgentOpsPage, ModelOpsPage } from "./pages/OpsManagementPage";
import {
  PermissionAclPage,
  PermissionHubPage,
  PermissionOrgsPage,
  PermissionRolesPage,
  PermissionUsersPage,
} from "./pages/PermissionPages";
import ResourceCostPage from "./pages/ResourceCostPage";
import UserAgentProfilePage from "./pages/UserAgentProfilePage";
import UserFeedbackPage from "./pages/UserFeedbackPage";

function useCurrentPath() {
  const [path, setPath] = useState(window.location.pathname);

  useEffect(() => {
    const onPopState = () => setPath(window.location.pathname);
    window.addEventListener("popstate", onPopState);
    return () => window.removeEventListener("popstate", onPopState);
  }, []);

  return path === "" ? "/" : path;
}

export default function App() {
  const path = useCurrentPath();
  const [toast, setToast] = useState<string | null>(null);

  useEffect(() => {
    if (!toast) return;
    const t = window.setTimeout(() => setToast(null), 2800);
    return () => window.clearTimeout(t);
  }, [toast]);

  let page = <BusinessDashboardPage />;
  if (path === "/feedback") page = <UserFeedbackPage />;
  else if (path === "/expert") page = <ExpertWorkbenchPage />;
  else if (path === "/model-board") page = <ModelBoardPage />;
  else if (path === "/resource-board") page = <ResourceBoardPage />;
  else if (path === "/resource-cost") page = <ResourceCostPage />;
  else if (path === "/profile") page = <UserAgentProfilePage />;
  else if (path === "/model-ops") page = <ModelOpsPage />;
  else if (path === "/agent-ops") page = <AgentOpsPage />;
  else if (path === "/permission") page = <PermissionHubPage currentPath={path} />;
  else if (path === "/permission/users") page = <PermissionUsersPage currentPath={path} />;
  else if (path === "/permission/orgs") page = <PermissionOrgsPage currentPath={path} />;
  else if (path === "/permission/roles") page = <PermissionRolesPage currentPath={path} />;
  else if (path === "/permission/acl") page = <PermissionAclPage currentPath={path} />;

  return (
    <OpsPageShell
      currentPath={path}
      toast={toast}
      onShowToast={setToast}
    >
      {page}
    </OpsPageShell>
  );
}

