import json
from pathlib import Path

def find_node(node, target):
    if node.get("id") == target:
        return node
    for c in node.get("children") or []:
        r = find_node(c, target)
        if r: return r
    return None

def color(fill):
    if not fill or fill.get("type") != "SOLID":
        return None
    c = fill.get("color", {})
    a = fill.get("opacity", c.get("a", 1))
    return f"rgba({int(c.get('r',0)*255)},{int(c.get('g',0)*255)},{int(c.get('b',0)*255)},{a:.2f})"

def summarize(node, depth=0, max_depth=5):
    if depth > max_depth:
        return []
    bb = node.get("absoluteBoundingBox") or {}
    fills = node.get("fills") or []
    bg = color(fills[0]) if fills else None
    name = node.get("name", "")
    typ = node.get("type", "")
    text = node.get("characters", "") if typ == "TEXT" else ""
    w, h = round(bb.get("width", 0)), round(bb.get("height", 0))
    x, y = round(bb.get("x", 0)), round(bb.get("y", 0))
    line = {"depth": depth, "name": name, "type": typ, "id": node.get("id"), "x": x, "y": y, "w": w, "h": h, "bg": bg, "text": text[:60] if text else ""}
    rows = [line]
    for c in node.get("children") or []:
        rows.extend(summarize(c, depth + 1, max_depth))
    return rows

