"""Extract 2026-05-21 adjusted frames (latest IDs on Page 1)."""
from __future__ import annotations

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
FIGMA = ROOT / "figma-file-raw.json"
OUT_DIR = Path(__file__).resolve().parents[1] / "frontend" / "src" / "data"

# 2026-05-21 后续调整 — 画板在 Page 1 后部（较大 node id）
FRAMES = {
    "aiHome": "0:13659",
    "feedback": "0:12861",
    "expert": "0:12408",
}


def find_node(node: dict, target: str) -> dict | None:
    if node.get("id") == target:
        return node
    for c in node.get("children") or []:
        r = find_node(c, target)
        if r:
            return r
    return None


def color_from_fills(fills: list) -> str | None:
    for fill in fills or []:
        if fill.get("visible") is False:
            continue
        if fill.get("type") == "SOLID":
            c = fill.get("color") or {}
            a = fill.get("opacity", c.get("a", 1))
            return f"#{int(c.get('r',0)*255):02x}{int(c.get('g',0)*255):02x}{int(c.get('b',0)*255):02x}"
    return None


def walk(node: dict, ox: float, oy: float, rows: list, depth: int = 0) -> None:
    bb = node.get("absoluteBoundingBox") or {}
    x, y = round(bb.get("x", 0) - ox, 1), round(bb.get("y", 0) - oy, 1)
    w, h = round(bb.get("width", 0), 1), round(bb.get("height", 0), 1)
    typ = node.get("type", "")
    text = ""
    if typ == "TEXT":
        text = " ".join(str(node.get("characters", "")).split())
    bg = color_from_fills(node.get("fills") or [])
    if text or (typ == "FRAME" and w > 40 and h > 24 and depth <= 8):
        rows.append(
            {
                "depth": depth,
                "name": node.get("name", ""),
                "type": typ,
                "id": node.get("id"),
                "x": x,
                "y": y,
                "w": w,
                "h": h,
                "bg": bg,
                "text": text,
            }
        )
    for c in node.get("children") or []:
        walk(c, ox, oy, rows, depth + 1)


def main() -> None:
    data = json.loads(FIGMA.read_text(encoding="utf-8-sig"))
    for key, fid in FRAMES.items():
