        texts = [r for r in rows if r["text"]]
        out = OUT_DIR / f"figma-v2-{key}.json"
        out.write_text(
            json.dumps({"frameId": fid, "texts": texts, "structure": rows[:120]}, ensure_ascii=False, indent=2),
            encoding="utf-8",
        )
        print(key, fid, "texts", len(texts), "->", out.name)
        for t in sorted(texts, key=lambda i: (i["y"], i["x"]))[:40]:
            if t["x"] >= 200:
                print(f"  {t['y']:4.0f} {t['x']:4.0f} {t['text'][:50]}")


if __name__ == "__main__":
    main()

