import json
import sys
from pathlib import Path

data = json.loads(Path(r"c:\Users\win\Desktop\program\figma-file-raw.json").read_text(encoding="utf-8-sig"))

def find_node(node, target):
    if node.get("id") == target:
        return node
    for c in node.get("children") or []:
        r = find_node(c, target)
        if r:
            return r
    return None

def collect(node, ox, oy, rows):
    if node.get("type") == "TEXT":
        t = " ".join(str(node.get("characters", "")).split())
        if t:
            bb = node.get("absoluteBoundingBox") or {}
            rows.append((round(bb.get("y", 0) - oy), round(bb.get("x", 0) - ox), t))
    for c in node.get("children") or []:
        collect(c, ox, oy, rows)

fid = sys.argv[1] if len(sys.argv) > 1 else "0:7209"
root = find_node(data["document"], fid)
bb = root["absoluteBoundingBox"]
rows = []
collect(root, bb["x"], bb["y"], rows)
for y, x, t in sorted(rows):
    if x >= 200:
        print(f"{y:4d} {x:4d} {t}")

