import { NavIcon } from "../icons/NavIcon";
import { isNavActive, SIDEBAR_FOOTER, SIDEBAR_SECTIONS } from "../../routes";

type OpsSideNavProps = {
  currentPath: string;
  onPlaceholder?: (label: string) => void;
};

export function OpsSideNav({ currentPath, onPlaceholder }: OpsSideNavProps) {
  return (
    <aside className="fg-sidebar">
      {SIDEBAR_SECTIONS.map((section) => (
        <div key={section.title} className="fg-sidebar-section">
          <div className="fg-sidebar-section-title">{section.title}</div>
          <nav>
            {section.items.map((item) => (
              <a
                key={item.path}
                className={isNavActive(currentPath, item.path) ? "active" : ""}
                href={item.path}
              >
                {item.icon ? <NavIcon name={item.icon} /> : null}
                <span>{item.label}</span>
              </a>
            ))}
          </nav>
        </div>
      ))}
      <nav className="fg-sidebar-footer">
        {SIDEBAR_FOOTER.map((item) => (
          <a
            key={item.label}
            href={item.path}
            onClick={
              item.placeholder
                ? (e) => {
                    e.preventDefault();
                    onPlaceholder?.(item.label);
                  }
                : undefined
            }
          >
            {item.label}
          </a>
        ))}
      </nav>
    </aside>
  );
}

