.fg-body {
  display: flex;
  flex: 1;
  min-height: 0;
}

.fg-sidebar {
  width: var(--fg-side);
  flex-shrink: 0;
  background: #fff;
  border-right: 1px solid var(--fg-border);
  padding: 16px 12px 20px;
  display: flex;
  flex-direction: column;
}

.fg-sidebar-section {
  margin-bottom: 8px;
}

.fg-sidebar-section-title {
  font-size: 12px;
  color: var(--fg-muted);
  padding: 8px 12px 4px;
