import { useMemo, useState, type ReactNode } from "react";

const TREND_DEFAULT = [28, 35, 32, 48, 55, 62, 58, 72, 68, 85, 78, 92, 88, 76, 65, 58, 72, 95, 100, 88, 72, 60, 45, 38];

export function FgPageHeader({ title, subtitle }: { title: string; subtitle?: string }) {
  return (
    <header className="fg-page-header">
      <h1>{title}</h1>
      {subtitle ? <p>{subtitle}</p> : null}
    </header>
  );
}

export function FgHealthBar({
  items,
  tabs,
  activeTab,
  onTab,
}: {
  items: { label: ReactNode; warn?: boolean }[];
  tabs?: string[];
  activeTab?: string;
  onTab?: (t: string) => void;
}) {
  return (
    <div className="fg-health-bar">
      <div className="fg-health-items">
        {items.map((item, i) => (
          <span key={i} className={item.warn ? "warn" : ""}>
            {item.label}
          </span>
        ))}
      </div>
      {tabs ? (
        <div className="fg-pill-group">
          {tabs.map((t) => (
            <button key={t} type="button" className={activeTab === t ? "on" : ""} onClick={() => onTab?.(t)}>
              {t}
            </button>
          ))}
        </div>
      ) : null}
    </div>
  );
}

export function FgSectionTitle({ children, action }: { children: ReactNode; action?: ReactNode }) {
  return (
    <div className="fg-section-head">
      <h2>{children}</h2>
      {action}
    </div>
  );
}

export function FgPillGroup<T extends string>({
  options,
  value,
  onChange,
}: {
  options: readonly T[];
  value: T;
  onChange: (v: T) => void;
}) {
  return (
    <div className="fg-pill-group">
      {options.map((o) => (
        <button key={o} type="button" className={value === o ? "on" : ""} onClick={() => onChange(o)}>
          {o}
        </button>
      ))}
    </div>
  );
}

export function FgMetricCard({
  label,
  value,
  delta,
  deltaTone = "neutral",
  highlight,
  progress,
}: {
  label: string;
  value: string;
  delta?: string;
  deltaTone?: "up" | "down" | "info" | "neutral";
  highlight?: boolean;
  progress?: number;
}) {
  return (
    <div className={`fg-metric-card ${highlight ? "highlight" : ""}`}>
      <span className="fg-metric-label">{label}</span>
      <strong className="fg-metric-value">{value}</strong>
      {delta ? <span className={`fg-metric-delta ${deltaTone}`}>{delta}</span> : null}
      {progress !== undefined ? (
        <div className="fg-metric-progress">
          <div style={{ width: `${progress}%` }} />
        </div>
      ) : null}
    </div>
  );
}

export function FgAreaChart({
  points = TREND_DEFAULT,
  peakLabel,
  xLabels = ["00:00", "04:00", "08:00", "12:00", "16:00", "20:00", "23:59"],
  gradientId = "areaFill",
}: {
  points?: number[];
  peakLabel?: string;
  xLabels?: string[];
  gradientId?: string;
}) {
  const pathPts = points.map((v, i) => `${(i / (points.length - 1)) * 800},${200 - v * 1.6}`).join(" ");
  return (
    <div className="fg-area-chart-wrap">
      <svg className="fg-area-chart" viewBox="0 0 800 200" preserveAspectRatio="none">
        <defs>
          <linearGradient id={gradientId} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor="#4dabf7" stopOpacity="0.35" />
            <stop offset="100%" stopColor="#4dabf7" stopOpacity="0.02" />
          </linearGradient>
        </defs>
        <path fill={`url(#${gradientId})`} d={`M0,200 L${pathPts} L800,200 Z`} />
        <polyline fill="none" stroke="#228be6" strokeWidth="2.5" points={pathPts} />
      </svg>
      {peakLabel ? <div className="fg-chart-peak">{peakLabel}</div> : null}
      <div className="fg-chart-xaxis">
        {xLabels.map((t) => (
          <span key={t}>{t}</span>
        ))}
      </div>
    </div>
  );
}

export function FgDonut({
  segments,
  center = ["Total", "100%"],
}: {
  segments: { color: string; end: number }[];
  center?: [string, string];
}) {
  let acc = 0;
  const stops = segments.map((s) => {
    const start = acc;
    acc = s.end;
    return `${s.color} ${start}% ${acc}%`;
  });
  return (
    <div className="fg-donut-wrap">
      <div className="fg-donut" style={{ background: `conic-gradient(${stops.join(", ")})` }}>
        <div className="fg-donut-hole">
          <span>{center[0]}</span>
          <strong>{center[1]}</strong>
        </div>
      </div>
    </div>
  );
}

const HEAT_LEVELS = ["#ebedf0", "#c6e48b", "#7bc96f", "#239a3b", "#196127"];

export function FgHeatmapCalendar({ title, bigValue, delta }: { title: string; bigValue: string; delta: string }) {
  const cells = useMemo(
    () => Array.from({ length: 52 * 7 }, (_, i) => HEAT_LEVELS[(i * 17) % HEAT_LEVELS.length]),
    [],
  );
  return (
    <section className="fg-card fg-heatmap-card">
      <div className="fg-heatmap-head">
        <div>
          <span className="fg-muted">{title}</span>
          <div className="fg-heatmap-big">{bigValue}</div>
          <span className="fg-metric-delta up">{delta}</span>
        </div>
      </div>
      <div className="fg-heatmap-grid">
        {cells.map((c, i) => (
          <span key={i} className="fg-heatmap-cell" style={{ background: c }} />
        ))}
      </div>
      <div className="fg-heatmap-axis">
        <span>2024-05-01</span>
        <span>2024-05-15</span>
        <span>2024-05-30</span>
      </div>
      <div className="fg-heatmap-legend">
        <span>少</span>
        {HEAT_LEVELS.map((c) => (
          <span key={c} className="fg-heatmap-cell" style={{ background: c }} />
        ))}
        <span>多</span>
      </div>
    </section>
  );
}

export function FgChartCard({
  title,
  pills,
  pillValue,
  onPill,
  children,
  action,
}: {
  title: string;
  pills?: string[];
  pillValue?: string;
  onPill?: (v: string) => void;
  children: ReactNode;
  action?: ReactNode;
}) {
  return (
    <section className="fg-card fg-chart-card">
      <div className="fg-card-toolbar">
        <h3>{title}</h3>
        <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
          {pills && pillValue && onPill ? <FgPillGroup options={pills} value={pillValue} onChange={onPill} /> : null}
          {action}
        </div>
      </div>
      {children}
    </section>
  );
}

export function FgSceneCard({
  title,
  pct,
  desc,
  success,
  token,
}: {
  title: string;
  pct: string;
  desc: string;
  success: string;
  token: string;
}) {
  return (
    <div className="fg-scene-card">
      <div className="fg-scene-head">
        <strong>{title}</strong>
        <em>{pct}</em>
      </div>
      <p>{desc}</p>
      <div className="fg-scene-foot">
        <span>成功率: {success}</span>
        <span>平均 Token: {token}</span>
      </div>
    </div>
  );
}

export function FgRankList({
  title,
  items,
}: {
  title: string;
  items: { rank: number; label: string; count: string; tag?: string }[];
}) {
  return (
    <section className="fg-card fg-rank-card">
      <h3>{title}</h3>
      <ol className="fg-rank-list">
        {items.map((it) => (
          <li key={it.rank}>
            <span className="fg-rank-num">{it.rank}</span>
            <div>
              <strong>{it.label}</strong>
              {it.tag ? <span className="fg-tag info">{it.tag}</span> : null}
            </div>
            <em>{it.count}</em>
          </li>
        ))}
      </ol>
    </section>
  );
}

export function FgDataTable({
  columns,
  rows,
}: {
  columns: string[];
  rows: ReactNode[][];
}) {
  return (
    <table className="fg-table">
      <thead>
        <tr>
          {columns.map((c) => (
            <th key={c}>{c}</th>
          ))}
        </tr>
      </thead>
      <tbody>
        {rows.map((row, i) => (
          <tr key={i}>
            {row.map((cell, j) => (
              <td key={j}>{cell}</td>
            ))}
          </tr>
        ))}
      </tbody>
    </table>
  );
}

export function FgCompareCard({
  badge,
  title,
  model,
  desc,
}: {
  badge: string;
  title: string;
  model: string;
  desc: string;
}) {
  return (
    <article className="fg-compare-card">
      <span className="fg-compare-badge">{badge}</span>
      <h4>{title}</h4>
      <strong>{model}</strong>
      <p>{desc}</p>
    </article>
  );
}

export function FgTabRow({
  tabs,
  active,
}: {
  tabs: { path: string; label: string }[];
  active: string;
}) {
  return (
    <nav className="fg-tab-row">
      {tabs.map((t) => (
        <a key={t.path} href={t.path} className={active === t.path ? "active" : ""}>
          {t.label}
        </a>
      ))}
    </nav>
  );
}

export function FgFilterBar({ children }: { children: ReactNode }) {
  return <div className="fg-filter-bar">{children}</div>;
}

export function FgSelect({ label, options }: { label: string; options: string[] }) {
  const [v, setV] = useState(options[0]);
  return (
    <label className="fg-select">
      <span>{label}</span>
      <select value={v} onChange={(e) => setV(e.target.value)}>
        {options.map((o) => (
          <option key={o}>{o}</option>
        ))}
      </select>
    </label>
  );
}

