#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""停止运营平台 Demo 前后端进程（按端口释放 5180 / 8001）。"""

from __future__ import annotations

import argparse
import json
import os
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent
STATE_FILE = ROOT / ".run" / "state.json"
BACKEND_PORT = 8001
FRONTEND_PORT = 5180


def _pids_on_port_windows(port: int) -> list[int]:
    try:
        out = subprocess.check_output(["netstat", "-ano"], text=True, encoding="utf-8", errors="replace")
    except (subprocess.CalledProcessError, FileNotFoundError):
        return []
    pids: list[int] = []
    token = f":{port}"
    for line in out.splitlines():
        if "LISTENING" not in line or token not in line:
            continue
        parts = line.split()
        if parts:
            try:
                pids.append(int(parts[-1]))
            except ValueError:
                pass
    return sorted(set(pids))


def _pids_on_port_unix(port: int) -> list[int]:
    try:
        out = subprocess.check_output(["lsof", "-ti", f":{port}"], text=True)
    except (subprocess.CalledProcessError, FileNotFoundError):
        return []
    pids: list[int] = []
    for line in out.splitlines():
        line = line.strip()
        if line.isdigit():
            pids.append(int(line))
    return sorted(set(pids))


def pids_on_port(port: int) -> list[int]:
    if os.name == "nt":
        return _pids_on_port_windows(port)
    return _pids_on_port_unix(port)


def kill_pid(pid: int) -> bool:
    try:
        if os.name == "nt":
            subprocess.check_call(["taskkill", "/PID", str(pid), "/T", "/F"], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        else:
            import signal

            os.kill(pid, signal.SIGTERM)
        return True
    except (OSError, subprocess.CalledProcessError):
        return False


def stop_ports(ports: list[int]) -> None:
    killed: set[int] = set()
    for port in ports:
        for pid in pids_on_port(port):
            if pid in killed:
                continue
            if kill_pid(pid):
                killed.add(pid)
                print(f"[stop] 端口 {port} -> 已结束 pid {pid}")
            else:
                print(f"[stop] 端口 {port} -> 无法结束 pid {pid}")


def run() -> int:
    parser = argparse.ArgumentParser(description="停止运营平台 Demo")
    parser.add_argument("--backend-only", action="store_true")
    parser.add_argument("--frontend-only", action="store_true")
    args = parser.parse_args()

    ports = []
    if args.backend_only:
        ports = [BACKEND_PORT]
    elif args.frontend_only:
        ports = [FRONTEND_PORT]
    else:
        ports = [FRONTEND_PORT, BACKEND_PORT]

    print(f"正在释放端口: {', '.join(str(p) for p in ports)}")
    stop_ports(ports)

    if STATE_FILE.exists():
        STATE_FILE.unlink()
        print("[stop] 已清除 .run/state.json")

    remaining = [p for p in ports if pids_on_port(p)]
    if remaining:
        print(f"[warn] 仍有端口占用: {remaining}")
        return 1
    print("[done] 服务已停止")
    return 0


if __name__ == "__main__":
    raise SystemExit(run())

#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""停止运营平台 Demo 前后端进程（按端口释放 5180 / 8001）。"""

from __future__ import annotations

import argparse
import os
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent
LOG_DIR = ROOT / ".logs"
LAUNCHER_LOG = LOG_DIR / "launcher.log"
STATE_FILE = ROOT / ".run" / "state.json"
BACKEND_PORT = 8001
FRONTEND_PORT = 5180

if os.name == "nt":
    CREATE_NO_WINDOW = 0x08000000
else:
    CREATE_NO_WINDOW = 0


def _say(msg: str, *, silent: bool) -> None:
    if silent:
        LOG_DIR.mkdir(parents=True, exist_ok=True)
        with LAUNCHER_LOG.open("a", encoding="utf-8") as f:
            f.write(msg.rstrip() + "\n")
    else:
        print(msg)


def _pids_on_port_windows(port: int) -> list[int]:
    kwargs: dict = {"text": True, "encoding": "utf-8", "errors": "replace"}
    if os.name == "nt":
        kwargs["creationflags"] = CREATE_NO_WINDOW
    try:
        out = subprocess.check_output(["netstat", "-ano"], **kwargs)
    except (subprocess.CalledProcessError, FileNotFoundError):
        return []
    pids: list[int] = []
    token = f":{port}"
    for line in out.splitlines():
        if "LISTENING" not in line or token not in line:
            continue
        parts = line.split()
        if parts:
            try:
                pids.append(int(parts[-1]))
            except ValueError:
                pass
    return sorted(set(pids))


def _pids_on_port_unix(port: int) -> list[int]:
    try:
        out = subprocess.check_output(["lsof", "-ti", f":{port}"], text=True)
    except (subprocess.CalledProcessError, FileNotFoundError):
        return []
    pids: list[int] = []
    for line in out.splitlines():
        line = line.strip()
        if line.isdigit():
            pids.append(int(line))
    return sorted(set(pids))


def pids_on_port(port: int) -> list[int]:
    if os.name == "nt":
        return _pids_on_port_windows(port)
    return _pids_on_port_unix(port)


def kill_pid(pid: int) -> bool:
    try:
        kwargs: dict = {"stdout": subprocess.DEVNULL, "stderr": subprocess.DEVNULL}
        if os.name == "nt":
            kwargs["creationflags"] = CREATE_NO_WINDOW
        if os.name == "nt":
            subprocess.check_call(["taskkill", "/PID", str(pid), "/T", "/F"], **kwargs)
        else:
            import signal

            os.kill(pid, signal.SIGTERM)
        return True
    except (OSError, subprocess.CalledProcessError):
        return False


def stop_ports(ports: list[int], *, silent: bool) -> None:
    killed: set[int] = set()
    for port in ports:
        for pid in pids_on_port(port):
            if pid in killed:
                continue
            if kill_pid(pid):
                killed.add(pid)
                _say(f"[stop] 端口 {port} -> pid {pid}", silent=silent)
            else:
                _say(f"[stop] 端口 {port} -> 无法结束 pid {pid}", silent=silent)


def run() -> int:
    parser = argparse.ArgumentParser(description="停止运营平台 Demo")
    parser.add_argument("--backend-only", action="store_true")
    parser.add_argument("--frontend-only", action="store_true")
    parser.add_argument("--silent", action="store_true", help="无控制台输出")
    args = parser.parse_args()

    silent = args.silent or (os.name == "nt" and Path(sys.executable).name.lower() == "pythonw.exe")

    ports: list[int]
    if args.backend_only:
        ports = [BACKEND_PORT]
    elif args.frontend_only:
        ports = [FRONTEND_PORT]
    else:
        ports = [FRONTEND_PORT, BACKEND_PORT]

    _say(f"释放端口: {ports}", silent=silent)
    stop_ports(ports, silent=silent)

    if STATE_FILE.exists():
        STATE_FILE.unlink()

    remaining = [p for p in ports if pids_on_port(p)]
    if remaining:
        _say(f"[warn] 仍有端口占用: {remaining}", silent=silent)
        return 1
    _say("[done] 服务已停止", silent=silent)
    return 0


if __name__ == "__main__":
    raise SystemExit(run())

#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""运营平台 Demo 一键启动。Windows 请双击「启动运营平台.vbs」，无黑窗。"""

from __future__ import annotations

import argparse
import json
import os
import shutil
import subprocess
import sys
import time
import urllib.error
import urllib.request
import webbrowser
from pathlib import Path

ROOT = Path(__file__).resolve().parent
BACKEND = ROOT / "backend"
FRONTEND = ROOT / "frontend"
VENV = BACKEND / ".venv"
DEMO_VENV = ROOT.parent / "aoqin-ai-demo-app" / "backend" / ".venv"
BUNDLED_NODE = ROOT.parent / "aoqin-ai-demo-app" / ".tools" / "node-v24.14.0-win-x64"
RUN_DIR = ROOT / ".run"
LOG_DIR = ROOT / ".logs"
LAUNCHER_LOG = LOG_DIR / "launcher.log"
STATE_FILE = RUN_DIR / "state.json"
BACKEND_PORT = 8001
FRONTEND_PORT = 5180
DEFAULT_OPEN_PATH = "/business"

if os.name == "nt":
    CREATE_NO_WINDOW = 0x08000000
    CREATE_NEW_PROCESS_GROUP = 0x00000200
else:
    CREATE_NO_WINDOW = 0
    CREATE_NEW_PROCESS_GROUP = 0


def _win_startupinfo() -> subprocess.STARTUPINFO | None:
    if os.name != "nt":
        return None
    si = subprocess.STARTUPINFO()
    si.dwFlags |= subprocess.STARTF_USESHOWWINDOW
    si.wShowWindow = 0  # SW_HIDE
    return si


def _win_hide_kwargs() -> dict:
    if os.name != "nt":
        return {"start_new_session": True}
    return {
        "creationflags": CREATE_NO_WINDOW | CREATE_NEW_PROCESS_GROUP,
        "startupinfo": _win_startupinfo(),
    }


def _venv_python() -> Path | None:
    for base in (VENV, DEMO_VENV):
        exe = base / "Scripts" / "python.exe"
        if not exe.exists():
            exe = base / "Scripts" / "python"
        if not exe.exists():
            exe = base / "bin" / "python"
        if exe.exists():
            return exe
    return None


def _venv_pythonw() -> Path | None:
    py = _venv_python()
    if not py:
        return None
    pw = py.parent / "pythonw.exe"
    return pw if pw.exists() else None


def _launcher_pythonw() -> Path | None:
    pw = _venv_pythonw()
    if pw:
        return pw
    fallback = Path(sys.executable).with_name("pythonw.exe")
    return fallback if fallback.exists() else None


def _prepend_node_path() -> None:
    if BUNDLED_NODE.exists():
        os.environ["PATH"] = str(BUNNED_NODE) + os.pathsep + os.environ.get("PATH", "")


def _node_exe() -> str:
    bundled = BUNDLED_NODE / "node.exe"
    if bundled.exists():
        return str(bundled)
    return shutil.which("node") or "node"


def _say(msg: str, *, silent: bool) -> None:
    if silent:
        LOG_DIR.mkdir(parents=True, exist_ok=True)
        with LAUNCHER_LOG.open("a", encoding="utf-8") as f:
            f.write(msg.rstrip() + "\n")
    else:
        print(msg)


def _wait_for_url(url: str, timeout: float = 45.0) -> bool:
    deadline = time.time() + timeout
    while time.time() < deadline:
        try:
            with urllib.request.urlopen(url, timeout=2) as resp:
                if resp.status < 500:
                    return True
        except (urllib.error.URLError, TimeoutError, OSError):
            time.sleep(0.6)
    return False


def _port_in_use(port: int) -> bool:
    import socket

    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
        try:
            s.bind(("127.0.0.1", port))
            return False
        except OSError:
            return True


def _run_cmd(cmd: list[str], cwd: Path, *, hide: bool) -> None:
    kwargs: dict = {"cwd": str(cwd)}
    if hide:
        kwargs.update(_win_hide_kwargs())
        kwargs["stdout"] = subprocess.DEVNULL
        kwargs["stderr"] = subprocess.DEVNULL
    subprocess.check_call(cmd, **kwargs)


def _spawn(cmd: list[str], cwd: Path, log_name: str, *, hide: bool) -> subprocess.Popen:
    LOG_DIR.mkdir(parents=True, exist_ok=True)
    log_path = LOG_DIR / log_name
    log_file = open(log_path, "a", encoding="utf-8")
    log_file.write(f"\n--- start {time.strftime('%Y-%m-%d %H:%M:%S')} ---\n")
    log_file.write(f"cmd: {' '.join(cmd)}\n")
    log_file.flush()

    kwargs: dict = {
        "cwd": str(cwd),
        "stdout": log_file,
        "stderr": subprocess.STDOUT,
        "stdin": subprocess.DEVNULL,
    }
    if hide:
        kwargs.update(_win_hide_kwargs())

    proc = subprocess.Popen(cmd, **kwargs)
    log_file.close()
    return proc


def _ensure_frontend_built(*, hide: bool) -> None:
    dist = FRONTEND / "dist" / "index.html"
    if dist.exists():
        return
    npm = "npm.cmd" if os.name == "nt" else "npm"
    _say("[build] 首次启动，正在构建前端（仅一次）…", silent=hide)
    _run_cmd([npm, "install"], FRONTEND, hide=hide)
    _run_cmd([npm, "run", "build"], FRONTEND, hide=hide)


def _frontend_cmd(*, silent: bool) -> tuple[list[str], Path]:
    """静默模式优先 pythonw 静态服务，避免 node/vite 弹出终端。"""
    if silent:
        dist = FRONTEND / "dist"
        if (dist / "index.html").exists():
            py = _venv_pythonw() or _launcher_pythonw() or _venv_python()
            if py:
                return (
                    [
                        str(py),
                        "-m",
                        "http.server",
                        str(FRONTEND_PORT),
                        "--bind",
                        "127.0.0.1",
                        "--directory",
                        str(dist),
                    ],
                    dist,
                )
    vite_js = FRONTEND / "node_modules" / "vite" / "bin" / "vite.js缓存.js"
    vite_js = FRONTEND / "node_modules" / "vite" / "bin" / "vite.js"
    if vite_js.exists():
        return (
            [_node_exe(), str(vite_js), "--host", "127.0.0.1", "--port", str(FRONTEND_PORT)],
            FRONTEND,
        )
    npm = "npm.cmd" if os.name == "nt" else "npm"
    return (
        [npm, "run", "dev", "--", "--host", "127.0.0.1", "--port", str(FRONTEND_PORT)],
        FRONTEND,
    )


def _save_state(*, open_path: str, backend_pid: int | None, frontend_pid: int) -> None:
    RUN_DIR.mkdir(parents=True, exist_ok=True)
    STATE_FILE.write_text(
        json.dumps(
            {
                "backend_port": BACKEND_PORT,
                "frontend_port": FRONTEND_PORT,
                "open_path": open_path,
                "backend_pid": backend_pid,
                "frontend_pid": frontend_pid,
                "started_at": time.strftime("%Y-%m-%d %H:%M:%S"),
            },
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )


def _maybe_relaunch_hidden(args: argparse.Namespace) -> bool:
    """从 python.exe / 终端启动时，转交 pythonw 无窗运行并立刻退出当前进程。"""
    if os.name != "nt" or args.foreground or os.environ.get("OPS_RELAUNCHED") == "1":
        return False
    if Path(sys.executable).name.lower() == "pythonw.exe":
        return False

    pythonw = _launcher_pythonw()
    if not pythonw:
        return False

    cmd = [str(pythonw), str(ROOT / "start_all.py"), "--silent"]
    if args.frontend_only:
        cmd.append("--frontend-only")
    if args.no_browser:
        cmd.append("--no-browser")
    if args.skip_install:
        cmd.append("--skip-install")
    if args.open != DEFAULT_OPEN_PATH:
        cmd.extend(["--open", args.open])

    env = os.environ.copy()
    env["OPS_RELAUNCHED"] = "1"
    subprocess.Popen(
        cmd,
        cwd=str(ROOT),
        stdin=subprocess.DEVNULL,
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
        env=env,
        close_fds=True,
        **_win_hide_kwargs(),
    )
    return True


def run() -> int:
    parser = argparse.ArgumentParser(description="启动运营平台 Demo")
    parser.add_argument("--frontend-only", action="store_true")
    parser.add_argument("--foreground", action="store_true", help="调试：保留终端")
    parser.add_argument("--silent", action="store_true", help="无窗静默")
    parser.add_argument("--no-browser", action="store_true")
    parser.add_argument("--skip-install", action="store_true")
    parser.add_argument("--open", default=DEFAULT_OPEN_PATH)
    args = parser.parse_args()

    if _maybe_relaunch_hidden(args):
        return 0

    silent = args.silent or (os.name == "nt" and Path(sys.executable).name.lower() == "pythonw.exe")
    hide = not args.foreground
    open_path = args.open if args.open.startswith("/") else f"/{args.open}"
    frontend_url = f"http://127.0.0.1:{FRONTEND_PORT}{open_path}"
    health_url = f"http://127.0.0.1:{FRONTEND_PORT}/"

    _prepend_node_path()

    if _port_in_use(FRONTEND_PORT):
        if not args.no_browser:
            webbrowser.open(frontend_url)
        return 0

    procs: list[subprocess.Popen] = []
    backend_pid: int | None = None

    if not args.frontend_only:
        if not _port_in_use(BACKEND_PORT):
            python = _venv_python()
            if python is None:
                _run_cmd([sys.executable, "-m", "venv", str(VENV)], ROOT, hide=hide)
                python = VENV / "Scripts" / "python.exe"
            pythonw = _venv_pythonw() or python
            pip = python.parent / ("pip.exe" if os.name == "nt" else "pip")
            if not args.skip_install and python.parent.parent == VENV:
                _run_cmd([str(pip), "install", "-r", "requirements.txt"], BACKEND, hide=hide)
            backend_proc = _spawn(
                [str(pythonw), "-m", "uvicorn", "app.main:app", "--host", "127.0.0.1", "--port", str(BACKEND_PORT)],
                BACKEND,
                "backend.log",
                hide=hide,
            )
            procs.append(backend_proc)
            backend_pid = backend_proc.pid

    if silent:
        _ensure_frontend_built(hide=hide)
    elif not (FRONTEND / "node_modules").exists() and not args.skip_install:
        npm = "npm.cmd" if os.name == "nt" else "npm"
        _run_cmd([npm, "install"], FRONTEND, hide=hide)

    fe_cmd, fe_cwd = _frontend_cmd(silent=silent)
    frontend_proc = _spawn(fe_cmd, fe_cwd, "frontend.log", hide=hide)
    procs.append(frontend_proc)

    if hide:
        _save_state(open_path=open_path, backend_pid=backend_pid, frontend_pid=frontend_proc.pid)

    if not args.no_browser:
        if _wait_for_url(health_url):
            webbrowser.open(frontend_url)
        _say(f"opened {frontend_url}", silent=silent)

    if hide:
        return 0

    try:
        for p in procs:
            p.wait()
    except KeyboardInterrupt:
        for p in procs:
            p.terminate()
    return 0


if __name__ == "__main__":
    raise SystemExit(run())

"""无控制台 SPA 静态服务，供静默启动使用。"""
from __future__ import annotations

import argparse
from http.server import SimpleHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path


class SPAHandler(SimpleHTTPRequestHandler):
    directory: Path

    def __init__(self, *args, **kwargs):
        super().__init__(*args, directory=str(self.directory), **kwargs)

    def do_GET(self) -> None:
        fs_path = Path(self.translate_path(self.path))
        if not fs_path.exists() or fs_path.is_dir():
            self.path = "/index.html"
        return super().do_GET()

    def log_message(self, fmt: str, *args) -> None:
        return


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--port", type=int, default=5180)
    parser.add_argument("--directory", required=True)
    args = parser.parse_args()

    directory = Path(args.directory).resolve()
    SPAHandler.directory = directory

    def handler(*h_args, **h_kwargs):
        return SPAHandler(*h_args, **h_kwargs)

    server = ThreadingHTTPServer(("127.0.0.1", args.port), handler)
    server.serve_forever()


if __name__ == "__main__":
    main()

